const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = {
  primary: "0a0a0a",
  secondary: "404040",
  accent: "0070F3",
  light: "e5e5e5",
  bg: "ffffff"
};

const PAGE_NUM_Y = 5.15;
const PAGE_NUM_X = 9.1;

function addPageBadge(slide, num) {
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: PAGE_NUM_X, y: PAGE_NUM_Y, w: 0.6, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.15
  });
  slide.addText(String(num).padStart(2, '0'), {
    x: PAGE_NUM_X, y: PAGE_NUM_Y, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });
}

function addTitle(slide, title) {
  slide.addText(title, {
    x: 0.5, y: 0.2, w: 9, h: 0.9,
    fontSize: 26, fontFace: "Arial",
    color: theme.primary, bold: true,
    valign: "middle"
  });
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 1.2, w: 9, h: 0,
    line: { color: theme.light, width: 2 }
  });
}

// Slide 1: Cover
let s1 = pres.addSlide();
s1.background = { color: theme.bg };
s1.addText("Measuring AI Ability to Complete\nLong Software Tasks", {
  x: 1, y: 1.5, w: 8, h: 1.5,
  fontSize: 44, fontFace: "Arial",
  color: theme.primary, bold: true, align: "center"
});
s1.addText("Time Horizon Doubling Every 7 Months", {
  x: 1, y: 3.2, w: 8, h: 0.8,
  fontSize: 24, fontFace: "Arial",
  color: theme.accent, bold: true, align: "center"
});
s1.addText("METR (Model Evaluation & Threat Research) | March 2025", {
  x: 1, y: 4.5, w: 8, h: 0.5,
  fontSize: 14, fontFace: "Arial",
  color: theme.secondary, align: "center"
});

// Slide 2: Methodology
let s2 = pres.addSlide();
s2.background = { color: theme.bg };
addTitle(s2, "A New Metric: 50% Task-Completion Time Horizon");
s2.addText([
  { text: "Methodology Overview:\n", options: { bold: true, fontSize: 18, color: theme.primary } },
  { text: "1. Create diverse task suite (170 tasks)\n", options: { bullet: true } },
  { text: "2. Measure human timing & AI success rates\n", options: { bullet: true } },
  { text: "3. Fit logistic model to find 50% success duration\n", options: { bullet: true } }
], {
  x: 0.5, y: 1.5, w: 4.5, h: 2,
  fontSize: 16, fontFace: "Arial", color: theme.secondary, lineSpacing: 32
});
s2.addImage({
  path: "/app/benchmark/assets/figure_2.jpg",
  x: 5.2, y: 1.5, w: 4.3, h: 3.5, sizing: { type: "contain" }
});
addPageBadge(s2, 2);

// Slide 3: Task Suite
let s3 = pres.addSlide();
s3.background = { color: theme.bg };
addTitle(s3, "170 Tasks Spanning 3 Seconds to 8 Hours of Human Effort");
s3.addText("Task Suite Composition:\n• HCAST: 97 tasks\n• SWAA: 66 tasks\n• RE-Bench: 7 tasks", {
  x: 0.5, y: 1.3, w: 9, h: 0.8,
  fontSize: 16, fontFace: "Arial", color: theme.secondary
});

let tableRows = [
  [
    { text: "Task Family", options: { bold: true, fill: theme.light, color: theme.primary, fontFace: "Arial" } },
    { text: "Human Time", options: { bold: true, fill: theme.light, color: theme.primary, fontFace: "Arial" } },
    { text: "Description", options: { bold: true, fill: theme.light, color: theme.primary, fontFace: "Arial" } }
  ],
  [ "find_shell_script", "3 seconds", "Which file is a shell script?" ],
  [ "wikipedia_research", "1 minute", "Research simple factual info" ],
  [ "oxdna_simple", "9 minutes", "Detect/fix bug in MD simulation" ],
  [ "munge_data", "56 minutes", "Python script to transform JSON" ],
  [ "cuda_backtesting", "8 hours", "Custom CUDA kernels for 30x speedup" ]
];

s3.addTable(tableRows, {
  x: 0.5, y: 2.3, w: 9, 
  rowH: 0.4,
  fill: "FFFFFF", color: theme.secondary,
  fontSize: 14, fontFace: "Arial",
  border: { type: "solid", color: theme.light, pt: 1 }
});
addPageBadge(s3, 3);

// Slide 4: Exponential Trend
let s4 = pres.addSlide();
s4.background = { color: theme.bg };
addTitle(s4, "AI Task Horizon Grew from 2 Seconds (GPT-2) to ~1 Hour 50 Minutes (o3) in 6 Years");

s4.addText([
  { text: "Key Metrics:\n", options: { bold: true, fontSize: 18, color: theme.primary } },
  { text: "• Doubling time: ~207 days (~7 months)\n", options: {} },
  { text: "• R² = 0.97 (highly consistent trend)\n\n", options: {} },
  { text: "Trajectory:\n", options: { bold: true, fontSize: 18, color: theme.primary } },
  { text: "• GPT-2 (2019): ~2 seconds\n", options: {} },
  { text: "• GPT-4 (2023): ~5 minutes\n", options: {} },
  { text: "• o3 (2025): ~1 hour 50 minutes\n", options: {} }
], {
  x: 0.5, y: 1.5, w: 4.5, h: 3,
  fontSize: 16, fontFace: "Arial", color: theme.secondary, lineSpacing: 24
});

s4.addImage({
  path: "/app/benchmark/assets/figure_1.jpg",
  x: 5.2, y: 1.5, w: 4.3, h: 3.5, sizing: { type: "contain" }
});
addPageBadge(s4, 4);

// Slide 5: Success Probability
let s5 = pres.addSlide();
s5.background = { color: theme.bg };
addTitle(s5, "Success Probability Drops Sharply as Task Length Increases for All Models");

s5.addText("Frontier models like Claude 3.7 Sonnet (54m) and o3 (1h50m) push the curve significantly rightward compared to older models.", {
  x: 0.5, y: 1.3, w: 9, h: 0.6,
  fontSize: 16, fontFace: "Arial", color: theme.secondary
});

s5.addImage({
  path: "/app/benchmark/assets/figure_3.jpg",
  x: 1.5, y: 2.0, w: 7, h: 3.2, sizing: { type: "contain" }
});
addPageBadge(s5, 5);

// Slide 6: Drivers & Limitations
let s6 = pres.addSlide();
s6.background = { color: theme.bg };
addTitle(s6, "Reasoning, Tool Use, and Error Recovery Drive Time Horizon Growth");

s6.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 0.5, y: 1.5, w: 4.25, h: 3, fill: { color: "F5F5F5" }, rectRadius: 0.1
});
s6.addText("Key Drivers of Progress", {
  x: 0.7, y: 1.7, w: 3.85, h: 0.4, fontSize: 20, fontFace: "Arial", color: theme.primary, bold: true
});
s6.addText("• Improved logical reasoning\n• Better tool use\n• Greater reliability in execution\n• Self-awareness\n• Ability to adapt to mistakes", {
  x: 0.7, y: 2.3, w: 3.85, h: 2, fontSize: 16, fontFace: "Arial", color: theme.secondary, lineSpacing: 32
});

s6.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 5.25, y: 1.5, w: 4.25, h: 3, fill: { color: "FFFDF5" }, rectRadius: 0.1
});
s6.addText("Current Limitations", {
  x: 5.45, y: 1.7, w: 3.85, h: 0.4, fontSize: 20, fontFace: "Arial", color: theme.primary, bold: true
});
s6.addText("• Poor performance on unstructured, 'messier' tasks\n• External validity: Tasks may not perfectly represent average real-world intellectual labor", {
  x: 5.45, y: 2.3, w: 3.85, h: 2, fontSize: 16, fontFace: "Arial", color: theme.secondary, lineSpacing: 32
});
addPageBadge(s6, 6);

// Slide 7: Extrapolation
let s7 = pres.addSlide();
s7.background = { color: theme.bg };
addTitle(s7, "Extrapolation Predicts Month-Long Task Automation by 2028–2031");

s7.addText([
  { text: "Projections & Caveats:\n", options: { bold: true, fontSize: 20, color: theme.primary } },
  { text: "• >1 Month Horizon (167 hours): Expected between mid-2028 and mid-2031\n", options: { bullet: true } },
  { text: "• Acceleration: The 2023–2025 growth rate is ~20% faster than the overall 2019–2025 trend\n", options: { bullet: true } },
  { text: "• Real-World Impact: Suggests automation of entire month-long software projects in the near future\n", options: { bullet: true } },
  { text: "• Caveat: Assuming external validity holds and trends don't plateau\n", options: { bullet: true } }
], {
  x: 0.5, y: 1.8, w: 9, h: 2.5,
  fontSize: 18, fontFace: "Arial", color: theme.secondary, lineSpacing: 36
});
addPageBadge(s7, 7);

// Slide 8: Takeaways
let s8 = pres.addSlide();
s8.background = { color: theme.bg };
addTitle(s8, "Takeaways: Exponential Autonomous Capability Growth Demands Proactive Safety Governance");

s8.addText([
  { text: "1. Robust Metric: ", options: { bold: true, color: theme.primary } },
  { text: "50% time horizon provides intuitive tracking (R²=0.97).\n\n", options: {} },
  { text: "2. Accelerating Trend: ", options: { bold: true, color: theme.primary } },
  { text: "Doubling every ~7 months, possibly faster since 2024.\n\n", options: {} },
  { text: "3. Current Frontier: ", options: { bold: true, color: theme.primary } },
  { text: "Models like o3 can complete ~2 hours of human-equivalent work.\n\n", options: {} },
  { text: "4. External Validity: ", options: { bold: true, color: theme.primary } },
  { text: "Still an open question on generalizability to all jobs.\n\n", options: {} },
  { text: "5. Next Steps: ", options: { bold: true, color: theme.primary } },
  { text: "Unstructured tasks remain a hurdle, but exponential growth demands proactive safety governance.\n", options: {} }
], {
  x: 0.5, y: 1.5, w: 9, h: 3.5,
  fontSize: 18, fontFace: "Arial", color: theme.secondary
});
addPageBadge(s8, 8);

pres.writeFile({ fileName: '/app/output/final_deck.pptx' }).then(() => {
  console.log('Presentation created successfully!');
}).catch(err => {
  console.error('Failed to create presentation:', err);
  process.exit(1);
});

